async def act(page):
    """
    Use the site's visible search widget (via the site-aware helper) to search for
    the keyword 'crypto' and click the third-to-last result. Use only
    accessibility-role-centric selectors (page.get_by_role) for all interactions
    and avoid CSS locators. If an overlay/dialog is present, attempt to dismiss
    it via accessible buttons before invoking the helper. Print the raw helper
    results exactly as returned.
    """
    import asyncio

    async def dismiss_overlay():
        """Try to close obvious overlays/dialogs using accessibility-role-centric
        selectors only. Returns True if an action was taken, False otherwise.
        """
        # 1) Try dialog-based closes
        dialogs = page.get_by_role("dialog")
        try:
            dialog_count = await dialogs.count()
        except Exception:
            dialog_count = 0

        close_names = [
            "close",
            "dismiss",
            "ok",
            "×",
            "x",
            "✕",
            "close popup",
            "dismiss popup",
            "close window",
        ]

        for i in range(dialog_count):
            dlg = dialogs.nth(i)
            # Named button attempts inside the dialog
            for name in close_names:
                btn = dlg.get_by_role("button", name=name)
                try:
                    btn_count = await btn.count()
                except Exception:
                    btn_count = 0
                if btn_count > 0:
                    try:
                        await btn.nth(0).click()
                        await page.wait_for_timeout(300)
                        return True
                    except Exception:
                        pass

            # Fallback: click the first button inside the dialog
            inner_buttons = dlg.get_by_role("button")
            try:
                inner_btn_count = await inner_buttons.count()
            except Exception:
                inner_btn_count = 0
            if inner_btn_count > 0:
                try:
                    await inner_buttons.nth(0).click()
                    await page.wait_for_timeout(300)
                    return True
                except Exception:
                    pass

        # 2) Top-level button heuristics (look for 'close' in accessible attributes/text)
        all_buttons = page.get_by_role("button")
        try:
            all_btn_count = await all_buttons.count()
        except Exception:
            all_btn_count = 0

        for i in range(all_btn_count):
            btn = all_buttons.nth(i)
            try:
                aria = await btn.get_attribute("aria-label") or ""
            except Exception:
                aria = ""
            try:
                title = await btn.get_attribute("title") or ""
            except Exception:
                title = ""
            try:
                txt = await btn.inner_text() or ""
            except Exception:
                txt = ""

            aria_l = aria.lower() if isinstance(aria, str) else ""
            title_l = title.lower() if isinstance(title, str) else ""
            txt_l = txt.strip().lower() if isinstance(txt, str) else ""

            if (
                ("close" in aria_l)
                or ("close" in title_l)
                or ("close" in txt_l)
                or (txt.strip() in ["×", "x", "✕"])
                or ("dismiss" in aria_l)
                or ("dismiss" in title_l)
                or ("dismiss" in txt_l)
            ):
                try:
                    await btn.click()
                    await page.wait_for_timeout(300)
                    return True
                except Exception:
                    pass

        # 3) Specific dismiss-named button
        dismiss_btn = page.get_by_role("button", name="dismiss")
        try:
            dismiss_count = await dismiss_btn.count()
        except Exception:
            dismiss_count = 0
        if dismiss_count > 0:
            try:
                await dismiss_btn.nth(0).click()
                await page.wait_for_timeout(300)
                return True
            except Exception:
                pass

        return False

    # Best-effort dismiss overlays before invoking the site-aware helper.
    try:
        await dismiss_overlay()
    except Exception:
        # ignore dismissal errors; helper will navigate to '/' itself
        pass

    # Use the knowledge-base helper to perform the visible search for 'crypto'.
    # This helper's first action is await page.goto('/').
    try:
        results = await create_curated_collection_by_search(page, "crypto", max_results=0, resolve_links=True)
    except Exception:
        results = []

    # Print the raw helper results exactly as returned.
    print(results)

    # If helper returned no results, try dismissing overlays and retry once.
    if not results:
        try:
            await dismiss_overlay()
        except Exception:
            pass
        try:
            results = await create_curated_collection_by_search(page, "crypto", max_results=0, resolve_links=True)
        except Exception:
            results = []
        print(results)

    # Now click the third-to-last article in role="main" -> role="article".
    main = page.get_by_role("main")
    articles = main.get_by_role("article")
    try:
        article_count = await articles.count()
    except Exception:
        article_count = 0

    if article_count < 3:
        raise Exception(f"Not enough search results to click the third-to-last (found {article_count}).")

    target_index = article_count - 3
    target_article = articles.nth(target_index)

    # Prefer clicking a link inside the article
    links = target_article.get_by_role("link")
    try:
        link_count = await links.count()
    except Exception:
        link_count = 0
    if link_count > 0:
        await links.nth(0).click()
        return

    # Fallback: click a heading inside the article
    headings = target_article.get_by_role("heading")
    try:
        heading_count = await headings.count()
    except Exception:
        heading_count = 0
    if heading_count > 0:
        await headings.nth(0).click()
        return

    # Final fallback: click the article container itself
    await target_article.click()
    return

